CREATE TABLE IF NOT EXISTS dados_cliente (
    id BIGSERIAL PRIMARY KEY,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    telefone TEXT UNIQUE NOT NULL,
    nomewpp TEXT,
    nome_responsavel TEXT,
    email_responsavel TEXT,
    tipo_evento TEXT,
    qtd_convidados INT,
    investimento TEXT,
    cidade TEXT,
    origem TEXT,
    nomes_evento TEXT,
    responsavel_legal TEXT,
    data_visita DATE,
    horario_visita_inicio TEXT,
    horario_visita_fim TEXT,
    visita_reagendada BOOLEAN DEFAULT FALSE,
    visita_cancelada BOOLEAN DEFAULT FALSE,
    data_evento DATE,
    horario_evento_inicio TEXT,
    horario_evento_fim TEXT,
    status_atendimento TEXT DEFAULT 'prospeccao'
);

CREATE OR REPLACE FUNCTION update_modified_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ language 'plpgsql';

DROP TRIGGER IF EXISTS update_dados_cliente_modtime ON dados_cliente;
CREATE TRIGGER update_dados_cliente_modtime
    BEFORE UPDATE ON dados_cliente
    FOR EACH ROW
    EXECUTE PROCEDURE update_modified_column();

-- Adicionar colunas novas caso a tabela já exista (ALTER TABLE seguro)
DO $$
BEGIN
    -- nome_responsavel
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='dados_cliente' AND column_name='nome_responsavel') THEN
        ALTER TABLE dados_cliente ADD COLUMN nome_responsavel TEXT;
    END IF;
    -- email_responsavel
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='dados_cliente' AND column_name='email_responsavel') THEN
        ALTER TABLE dados_cliente ADD COLUMN email_responsavel TEXT;
    END IF;
    -- qtd_convidados
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='dados_cliente' AND column_name='qtd_convidados') THEN
        ALTER TABLE dados_cliente ADD COLUMN qtd_convidados INT;
    END IF;
    -- investimento
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='dados_cliente' AND column_name='investimento') THEN
        ALTER TABLE dados_cliente ADD COLUMN investimento TEXT;
    END IF;
    -- nomes_evento
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='dados_cliente' AND column_name='nomes_evento') THEN
        ALTER TABLE dados_cliente ADD COLUMN nomes_evento TEXT;
    END IF;
    -- responsavel_legal
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='dados_cliente' AND column_name='responsavel_legal') THEN
        ALTER TABLE dados_cliente ADD COLUMN responsavel_legal TEXT;
    END IF;
    -- data_visita
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='dados_cliente' AND column_name='data_visita') THEN
        ALTER TABLE dados_cliente ADD COLUMN data_visita DATE;
    END IF;
    -- horario_visita_inicio
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='dados_cliente' AND column_name='horario_visita_inicio') THEN
        ALTER TABLE dados_cliente ADD COLUMN horario_visita_inicio TEXT;
    END IF;
    -- horario_visita_fim
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='dados_cliente' AND column_name='horario_visita_fim') THEN
        ALTER TABLE dados_cliente ADD COLUMN horario_visita_fim TEXT;
    END IF;
    -- visita_reagendada
