const output = items[0].json.output || '';

let raw = output
  .replace(/\[CRM:[^\]]+\]/g, '')
  .replace(/\[PDF:[^\]]+\]/g, '')
  .replace(/<function[^>]*>.*?<\/function>/gs, '')
  .replace(/<tool_call>.*?<\/tool_call>/gs, '')
  .trim();

const parts = raw.split('||').map(p => p.trim()).filter(p => p.length > 0);

return parts.map(text => {
  // 1s a 4s dependendo do tamanho do texto — rápido mas humano
  const base = Math.min(text.length * 0.04, 2.5);
  const aleatorio = Math.random() * 1.5;
  const delaySec = Math.max(1, Math.round(base + aleatorio));
  return { json: { text, delaySec } };
});

